draw:
function draw(ctx, t, W, H) {
  ctx.save();
  ctx.fillStyle = '#f5f0e8';
  ctx.fillRect(0, 0, W, H);

  // draw a stick figure representing an individual
  ctx.strokeStyle = 'black';
  ctx.lineWidth = 3;
  ctx.beginPath();
  ctx.arc(W/2, H/2, 20, 0, 2*Math.PI);
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(W/2, H/2 + 20);
  ctx.lineTo(W/2, H/2 + 50);
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(W/2, H/2 + 50);
  ctx.lineTo(W/2 - 20, H/2 + 70);
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(W/2, H/2 + 50);
  ctx.lineTo(W/2 + 20, H/2 + 70);
  ctx.stroke();

  // draw broken chains around the individual
  ctx.lineWidth = 5;
  ctx.beginPath();
  ctx.moveTo(W/2 - 50 + 20*Math.sin(t), H/2 - 50 + 20*Math.cos(t));
  ctx.lineTo(W/2 - 30 + 20*Math.sin(t + Math.PI/2), H/2 - 30 + 20*Math.cos(t + Math.PI/2));
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(W/2 + 50 + 20*Math.sin(t + Math.PI), H/2 - 50 + 20*Math.cos(t + Math.PI));
  ctx.lineTo(W/2 + 30 + 20*Math.sin(t + 3*Math.PI/2), H/2 - 30 + 20*Math.cos(t + 3*Math.PI/2));
  ctx.stroke();

  // add a broken link at the end of the chain
  ctx.lineWidth = 5;
  ctx.beginPath();
  ctx.arc(W/2 - 30 + 20*Math.sin(t + Math.PI/2), H/2 - 30 + 20*Math.cos(t + Math.PI/2), 5, 0, 2*Math.PI);
  ctx.stroke();
  ctx.beginPath();
  ctx.arc(W/2 + 30 + 20*Math.sin(t + 3*Math.PI/2), H/2 - 30 + 20*Math.cos(t + 3*Math.PI/2), 5, 0, 2*Math.PI);
  ctx.stroke();

  ctx.restore();
}
